```c
int
is_gil_enabled(void)
{
    PyObject *sys_mod = NULL;
    PyObject *func = NULL;
    PyObject *res = NULL;
    int ret = -1;

    sys_mod = PyImport_ImportModule("sys");
    if (sys_mod == NULL) {
        return -1;
    }

    func = PyObject_GetAttrString(sys_mod, "_is_gil_enabled");
    if (func == NULL) {
        if (PyErr_ExceptionMatches(PyExc_AttributeError)) {
            PyErr_Clear();
            ret = 1;
        }
        goto done;
    }

    if (!PyCallable_Check(func)) {
        ret = 1;
        goto done;
    }

    res = PyObject_CallNoArgs(func);
    if (res == NULL) {
        ret = -1;
        goto done;
    }

    ret = PyObject_IsTrue(res);

done:
    Py_XDECREF(res);
    Py_XDECREF(func);
    Py_DECREF(sys_mod);
    return ret;
}
```

